import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentTimetable({ user }) {
  const [timetable, setTimetable] = useState([]);
  const [loading, setLoading] = useState(true);
  const studentGrade = user?.grade || "Grade 8";

  // 🟢 Fallback Sample Classes (Database offline හෝ data නැතිනම් පෙන්වීමට)
  const defaultClasses = [
    { grade: 'Grade 8', day: 'Wednesday', subject: 'English', time_slot: '2.45 PM - 4.45 PM', teacher: 'Ranga Rajaguru' },
    { grade: 'Grade 8', day: 'Saturday', subject: 'Science', time_slot: '2.15 PM - 4.15 PM', teacher: 'Ravindu Jayaweera' },
    { grade: 'Grade 8', day: 'Tuesday', subject: 'Mathematics', time_slot: '4.45 PM - 6.45 PM', teacher: 'Buddhika Darshani' },
    { grade: 'Grade 6', day: 'Tuesday', subject: 'English', time_slot: '2.30 PM - 4.30 PM', teacher: 'Ranga Rajaguru' }
  ];

  useEffect(() => {
    setLoading(true);
    // LocalStorage එකේ ඇති data මුලින් පරීක්ෂා කිරීම
    const saved = localStorage.getItem('aura_timetable');
    let localData = saved ? JSON.parse(saved) : defaultClasses;

    axios.get('http://localhost:8082/api/timetable')
      .then(res => {
        const data = res.data && res.data.length > 0 ? res.data : localData;
        
        // Studentගේ Grade එකට ගැලපෙන classes විතරක් filter කිරීම
        const targetNum = String(studentGrade).replace(/\D/g, '');
        const filtered = data.filter(t => (t.grade || '').replace(/\D/g, '') === targetNum);

        setTimetable(filtered.length > 0 ? filtered : defaultClasses.filter(t => (t.grade || '').replace(/\D/g, '') === targetNum));
        setLoading(false);
      })
      .catch(() => {
        const targetNum = String(studentGrade).replace(/\D/g, '');
        const filtered = localData.filter(t => (t.grade || '').replace(/\D/g, '') === targetNum);
        setTimetable(filtered.length > 0 ? filtered : defaultClasses.filter(t => (t.grade || '').replace(/\D/g, '') === targetNum));
        setLoading(false);
      });
  }, [studentGrade]);

  return (
    <div style={styles.whiteBox}>
      
      {/* Title & Badge Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', flexWrap: 'wrap', gap: '10px' }}>
        <div>
          <h3 style={{ margin: 0, fontSize: '20px', color: '#1e293b', fontWeight: '800' }}>
            🗓️ Live Weekly Class Timetable
          </h3>
          <p style={{ margin: '4px 0 0 0', fontSize: '13px', color: '#64748b', fontWeight: '500' }}>
            Official class schedule mapped for <b>{studentGrade}</b>
          </p>
        </div>

        <span style={{ backgroundColor: '#dcfce7', color: '#15803d', padding: '6px 14px', borderRadius: '20px', fontSize: '12px', fontWeight: 'bold', border: '1px solid #bbf7d0' }}>
          🎓 {studentGrade} Active Schedule
        </span>
      </div>

      {/* Main Timetable Matrix View */}
      {loading ? (
        <div style={{ padding: '40px', textAlign: 'center', color: '#64748b', fontSize: '14px' }}>
          Loading timetable schedules...
        </div>
      ) : timetable.length > 0 ? (
        <div style={{ backgroundColor: '#ffffff', borderRadius: '12px', overflow: 'hidden', border: '1px solid #e2e8f0' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead>
              <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                <th style={{ padding: '14px 18px', color: '#64748b', fontSize: '13px', fontWeight: '700' }}>Day</th>
                <th style={{ padding: '14px 18px', color: '#64748b', fontSize: '13px', fontWeight: '700' }}>Subject</th>
                <th style={{ padding: '14px 18px', color: '#64748b', fontSize: '13px', fontWeight: '700' }}>Time Window</th>
                <th style={{ padding: '14px 18px', color: '#64748b', fontSize: '13px', fontWeight: '700' }}>Assigned Lecturer</th>
              </tr>
            </thead>
            <tbody>
              {timetable.map((item, index) => (
                <tr key={index} style={{ borderBottom: index === timetable.length - 1 ? 'none' : '1px solid #f1f5f9' }}>
                  <td style={{ padding: '16px 18px', fontWeight: '800', color: '#1e293b', fontSize: '14px' }}>
                    {item.day}
                  </td>
                  <td style={{ padding: '16px 18px', fontWeight: '800', color: '#0284c7', fontSize: '14px' }}>
                    {item.subject}
                  </td>
                  <td style={{ padding: '16px 18px', fontWeight: '600', color: '#ea580c', fontSize: '13.5px' }}>
                    {item.time_slot}
                  </td>
                  <td style={{ padding: '16px 18px', fontWeight: '800', color: '#15803d', fontSize: '14px' }}>
                    👨‍🏫 <span style={{ textDecoration: 'underline' }}>{item.teacher}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <div style={{ textAlign: 'center', padding: '40px 20px', backgroundColor: '#f8fafc', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
          <div style={{ fontSize: '38px', marginBottom: '8px' }}>📅</div>
          <h4 style={{ margin: '0 0 6px 0', fontSize: '16px', color: '#1e293b' }}>No Classes Scheduled Yet</h4>
          <p style={{ margin: 0, fontSize: '13px', color: '#64748b' }}>
            Weekly class schedule for <b>{studentGrade}</b> will be published here by the administration soon.
          </p>
        </div>
      )}

    </div>
  );
}

const styles = {
  whiteBox: { 
    backgroundColor: '#ffffff', 
    padding: '24px', 
    borderRadius: '16px', 
    border: '1px solid #e2e8f0', 
    boxShadow: '0 4px 15px rgba(0,0,0,0.03)' 
  }
};
